import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final long MOD = 1000000007L;
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();

        if (k == 0) {
            System.out.println(powMod(p, p - 1, MOD));
        } else if (k == 1) {
            System.out.println(powMod(p, p, MOD));
        } else {
            int[] pattern = new int[p];
            int length = 1;
            pattern[0] = 1;
            while (true) {
                int nextVal = (int)((long)pattern[length - 1] * k % p);
                boolean found = false;
                for (int i = 0; i < length; i++) {
                    if (pattern[i] == nextVal) {
                        found = true;
                        break;
                    }
                }
                if (found) {
                    break;
                }
                pattern[length] = nextVal;
                length++;
            }
            System.out.println(powMod(p, (p - 1) / length, MOD));
        }
        scanner.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
